/* V9 changes presentation only. The V8 story and source objects remain authoritative. */
(() => {
'use strict';
const d=window.PITSTOP, sources=window.PITSTOP_SOURCES||{}, root=document.getElementById('newsletter');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const href=id=>'versions/v9/#'+encodeURIComponent(id);
const asset=src=>esc(src);
const link=(url,label,cls='')=>/^https:\/\//.test(url||'')?`<a class="${cls}" href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:'';
function title(s){const mark=d.colourSystem.pages[s.id].emphasis,at=s.title.indexOf(mark);return at<0?esc(s.title):esc(s.title.slice(0,at))+`<span class="headline-mark">${esc(mark)}</span>`+esc(s.title.slice(at+mark.length));}
function art(s){return `<figure class="art art-${esc(s.visual.type)}"><img src="${asset(s.visual.src)}" data-fallback="${asset(s.visual.fallbackSrc||s.visual.src)}" alt="${esc(s.visual.alt)}" loading="lazy" decoding="async" width="${s.visual.type==='spot'?400:1200}" height="${s.visual.type==='spot'?205:800}"></figure>`;}
function notes(s){const urls=s.sourceLinks||sources.stories?.[s.id]||[];return `<details class="notes"><summary>Story notes & sources <span aria-hidden="true">＋</span></summary><div class="notes-body"><p class="credit">${esc(s.sourceCredit||s.credit)}</p>${[s.note,sources.context?.[s.id],sources.unavailable?.[s.id]].filter(Boolean).map(t=>`<p>${esc(t)}</p>`).join('')}${s.foot?`<p>${esc(s.foot)}</p>`:''}<div class="source-links">${urls.map(u=>link(u.url,u.label)+(u.detail?`<small>${esc(u.detail)}</small>`:'')).join('')}</div><details class="original"><summary>Full supplied update</summary><p>${esc(s.originalBody||s.body)}</p></details>${s.images?.length>1?s.images.slice(1).map(n=>`<img class="extra-art" src="${asset(s.imageFiles[n])}" alt="Additional supplied illustration of the Diwali celebration." loading="lazy">`).join(''):''}</div></details>`;}
function story(id,size=''){const s=d.stories.find(s=>s.id===id),style=d.colourSystem.pages[id];return `<article class="story ${size} treatment-${esc(style.layout)}" id="${esc(id)}" data-story="${esc(id)}" data-paper="${esc(style.paper)}" aria-labelledby="title-${esc(id)}"><div class="story-inner"><div class="story-copy"><p class="eyebrow">${esc(s.label)}</p><h3 id="title-${esc(id)}">${title(s)}</h3><div class="body">${s.body.split(/\n\n/).map(t=>`<p>${esc(t)}</p>`).join('')}</div>${s.link?link(s.link,s.linkLabel||'Read more','story-link'):''}</div>${art(s)}</div>${notes(s)}</article>`;}
const rows={business:story('growth','lead')+`<div class="pair">${story('ecosystem')}${story('lending')}</div><div class="pair">${story('frontier')}${story('startup')}</div><div class="pair quiet-pair">${story('finance')}${story('close')}</div>`,builders:story('academy','lead')+`<div class="release-list">${['dealer','miles','leads','approvals','saarathi','ownership','security'].map(id=>story(id,'release')).join('')}</div><div class="pair">${story('codex')}${story('hackathon')}</div>`,life:story('diwali','lead')+`<div class="pair">${story('milo')}${story('badminton')}</div><div class="pair">${story('survey')}${story('thermostat')}</div>`,perspectives:`<div class="pair voices">${['ambition','controls','inflection','safeguards'].map(id=>story(id,'voice')).join('')}</div>`};
root.innerHTML=`<section class="cover" id="cover" aria-labelledby="cover-title"><div class="cover-copy"><p class="eyebrow">The October issue <span aria-hidden="true">✦</span> 2026</p><h1 id="cover-title">The Pitstop</h1><p class="cover-subtitle">What’s happening<br> across Cars24.</p><a class="read-button" href="${href('briefing')}">Open this issue <span aria-hidden="true">↓</span></a><p class="cover-caption">26 stories. Four chapters. One good catch-up.</p></div><figure class="cover-art"><picture><source media="(max-width:600px)" srcset="assets/cover-wide.webp"><img src="assets/cover-portrait.webp" data-fallback="assets/cover-portrait.png" alt="The original Pitstop colleagues gathered around their laptop." width="941" height="1672" fetchpriority="high"></picture></figure></section>
<section class="briefing wrap" id="briefing" aria-labelledby="briefing-title"><div class="briefing-intro"><p class="eyebrow">Your monthly catch-up</p><h2 id="briefing-title">In this issue</h2><p>Results, things we’ve built, and the people behind them.</p></div><div class="briefing-chapters">${d.chapters.map(ch=>`<a href="${href(ch.id)}"><span class="chapter-number">0${ch.number}</span><span>${esc(ch.name)}<small>${ch.stories.length} stories</small></span><span aria-hidden="true">↘</span></a>`).join('')}</div></section>
<nav class="chapter-nav" aria-label="Newsletter chapters"><div class="nav-inner"><a href="${href('cover')}" class="nav-top" aria-label="Back to top">↑</a>${d.chapters.map(ch=>`<a href="${href(ch.id)}" data-chapter="${ch.id}"><span>0${ch.number}</span> ${esc(({business:'Business',builders:'Builders',life:'Life',perspectives:'Voices'})[ch.id])}</a>`).join('')}<span class="nav-progress" aria-hidden="true"></span></div></nav>
<div class="wrap chapters">${d.chapters.map(ch=>`<section class="chapter" id="${ch.id}" aria-labelledby="heading-${ch.id}"><header class="chapter-heading"><span class="chapter-number">0${ch.number}</span><div><h2 id="heading-${ch.id}">${esc(ch.name)}</h2><p>${esc(ch.body)}</p></div><span class="chapter-count">${ch.stories.length} stories</span></header>${rows[ch.id]}<a class="chapter-return" href="${href('briefing')}">Back to contents ↑</a></section>`).join('')}</div>
<footer class="ending" id="caught-up"><p class="eyebrow">You’re all caught up <span aria-hidden="true">✦</span></p><h2>That’s this month’s Pitstop.</h2><p>Have a win, a lesson, or a teammate’s story for the next issue?</p>${link(d.form,'Add your story','read-button')}<a href="${href('cover')}" class="read-again">Read again ↑</a><div class="colophon"><img src="assets/cars24-logo-black.svg" alt="Cars24" width="80" height="22"><span>The Pitstop · October 2026 · V9</span></div></footer>`;
for(const el of document.querySelectorAll('[data-paper]')){const paper=el.dataset.paper;el.style.setProperty('--page-stock',d.colourSystem.stocks[paper].hex);el.style.setProperty('--paper-art',`url('../../assets/flatland/${paper}.svg')`);}
for(const img of document.querySelectorAll('img[data-fallback]'))img.addEventListener('error',()=>{if(img.dataset.fallback){img.src=img.dataset.fallback;delete img.dataset.fallback;}},{once:true});
// Native document scrolling: links, browser find, text selection, and keyboard reading all work normally.
const navLinks=[...document.querySelectorAll('[data-chapter]')],chapters=[...document.querySelectorAll('.chapter')];
let frame=0;function update(){frame=0;const active=chapters.filter(el=>el.getBoundingClientRect().top<=180).at(-1);for(const a of navLinks){if(a.dataset.chapter===active?.id)a.setAttribute('aria-current','location');else a.removeAttribute('aria-current');}const max=document.documentElement.scrollHeight-innerHeight;document.querySelector('.nav-progress').style.transform=`scaleX(${max>0?Math.min(1,Math.max(0,scrollY/max)):0})`;}
addEventListener('scroll',()=>{if(!frame)frame=requestAnimationFrame(update);},{passive:true});addEventListener('resize',update);document.fonts?.ready.then(update);update();
// A base URL is used for V8's shared assets; restore this edition's story deep links after rendering.
const initialHash=location.hash;
if(initialHash){const loaded=document.readyState==='complete'?Promise.resolve():new Promise(resolve=>addEventListener('load',resolve,{once:true}));Promise.all([loaded,document.fonts?.ready]).then(()=>requestAnimationFrame(()=>{if(location.hash!==initialHash)return;let id;try{id=decodeURIComponent(initialHash.slice(1))}catch{return}document.getElementById(id)?.scrollIntoView({behavior:'instant',block:'start'});}));}
})();
